//! The thread through the valleys' words (`docs/LORE.md`, "The thread"):
//! which places each note and terminal speaks of, so the tests can hold
//! every mention to a real place and every note to the thread. The words
//! themselves are in the maps (generated by `scripts/place_notes.py`) and
//! the staged scenes (`assets/data/scenes.ron`).
//!
//! And the arc ([`BEATS`]): Hana's thread told a beat per rank of the
//! driver's job ladder, ending at the recall.

use bevy::prelude::*;

/// The three valleys a career moves between (the training yard has signs,
/// not story).
pub const VALLEYS: [&str; 3] = ["marrow_creek", "kettle_pass", "cinder_works"];

/// A note or terminal (by its marker's name, in its map) and the places it
/// speaks of: (map, name of a marker, region, road, river or wood there).
pub struct Lead {
    pub map: &'static str,
    pub note: &'static str,
    pub mentions: &'static [(&'static str, &'static str)],
}

